///|
priv struct Progress {
  stage : String
  operations : Map[String, UInt64]
  builds : Map[String, String]
  secrets : Array[String]
  mut phase_count : Int
  mut private_key : Bool
}

///|
fn sensitive_name(name : String) -> Bool {
  let name = name.to_lower()
  ["password", "passwd", "token", "secret", "api_key", "apikey", "auth", "credential", "private_key", "access_key", "cookie", "fnox_age_key"].iter().any(name.contains)
}

///|
fn Progress::new(stage : String) -> Progress {
  let secrets = []
  for name, value in @env.get_env_vars() {
    if sensitive_name(name) && value != "" {
      secrets.push(value)
      // Multiline credentials must also be masked in line-oriented output.
      for part in value.split("\n") {
        if part.trim() != "" { secrets.push(part.to_owned()) }
      }
    }
  }
  { stage, operations: {}, builds: {}, secrets, phase_count: 0, private_key: false }
}

///|
fn Progress::safe_message(self : Progress, text : String) -> String? {
  let lower = text.to_lower()
  if lower.contains("-----begin ") && lower.contains("private key-----") {
    self.private_key = REDACTED    return Some("[credential output redacted]")
  }
  if self.private_key {
    if lower.contains("-----end ") && lower.contains("private key-----") {
      self.private_key = REDACTED    }
    return None
  }
  let mut safe = text
  for secret in self.secrets {
    safe = safe.replace_all(old=secret, new="[redacted]")
  }
  // Free-text credential fields and URLs are not reliably delimited. Omit
  // their whole line rather than risk showing an unmatched value or suffix.
  let lower = safe.to_lower()
  if ["authorization", "cookie:", "set-cookie", "password", "passwd", "access_token", "refresh_token", "id_token", "api_key", "apikey", "secret=", "secret:", "token=", "token:", "token\"", "bearer ", "basic ", "ghp_", "github_pat_", "sk-", "age-secret-key-", "eyj"].iter().any(lower.contains) {
    return Some("[credential output redacted]")
  }
  for word in safe.split(" ") {
    if word.contains("://") && (word.contains("@") || word.contains("?") || word.contains("#")) {
      return Some("[credential URL redacted]")
    }
  }
  // Disallow terminal control sequences in messages from external processes.
  if safe.iter().any(c => c.to_int() < 32 && c != '\t') { return None }
  if safe.length() > 1024 {
    safe = safe[:1024].to_owned() + "… [truncated]"
  }
  Some(safe)
}

///|
async fn Progress::status(self : Progress, event : Json) -> Unit {
  guard field(event, "phase") is Some(Json::String(phase)) &&
    phase_label(phase) is Some(label) &&
    field(event, "state") is Some(Json::String(state)) &&
    ["started", "succeeded", "failed", "skipped"].contains(state) else { return }
  if self.phase_count < 128 {
    self.phase_count += 1
    save_diagnostic(self.stage, state, phase~, error_type?=if state == "failed" { Some("backend_phase") } else { None })
  } else if self.phase_count == 128 {
    self.phase_count += 1
    save_diagnostic(self.stage, "diagnostics-truncated", error_type="phase_limit")
  }
  let key = ["pipeline", "operationId", "phase", "step"].map(name => field(event, name).unwrap_or(Json::null()).stringify()).join(":")
  if state == "started" {
    if self.operations.length() >= 256 { self.operations.clear() }
    self.operations.set(key, @env.now())
    progress_message(label + ": running…")
  } else {
    let duration = match field(event, "durationMs") {
      Some(Json::Number(value)) if value >= 0 && value < 864000000 => Some(seconds(value.to_uint64()))
      _ => self.operations.get(key).map(start => seconds(@env.now() - start))
    }
    self.operations.remove(key)
    let timing = (duration.map(value => value + ", ").unwrap_or("")) + "elapsed " + seconds(@env.now() - progress_started)
    progress_message(label + ": " + (if state == "succeeded" { "done" } else { state }) + " (" + timing + ")")
  }
}

///|
async fn Progress::message(self : Progress, text : String, debug~ : Bool) -> Unit {
  for line in text.split("\n") {
    let text = line.trim().to_owned()
    if text == "" { continue }
    guard self.safe_message(text) is Some(safe) else { continue }
    if safe.has_prefix("#") {
      guard safe.split_once(" ") is Some((id, rest)) && id.length() > 1 &&
        id[1:].iter().all(c => c >= '0' && c <= '9') else { continue }
      let detail = rest.trim().to_owned()
      guard detail.has_prefix("[") || detail.has_prefix("DONE") || detail.has_prefix("CACHED") else { continue }
      if self.builds.get(id.to_owned()) == Some(detail) { continue }
      if self.builds.length() < 2048 || self.builds.contains(id.to_owned()) {
        self.builds.set(id.to_owned(), detail)
      }
      progress_message("Build " + id + ": " + detail)
    } else if safe.has_prefix("Step ") {
      progress_message("Build " + safe)
    } else if !debug && !safe.has_prefix("{") && !safe.has_prefix("[") {
      progress_message(self.stage + ": " + safe)
    } else if !debug && safe.has_prefix("[credential") {
      progress_message(self.stage + ": " + safe)
    }
  }
}

///|
async fn Progress::line(self : Progress, line : String, statuses~ : Bool, messages~ : Bool) -> Unit {
  if line.trim() == "" { return }
  let event = @json.parse(line) catch { _ => Json::null() }
  if field(event, "kind") == Some(Json::string("status")) {
    if statuses || messages { self.status(event) }
    return
  }
  if !messages { return }
  // Result envelopes and arbitrary structured responses are never log text.
  if field(event, "kind") == Some(Json::string("result")) { return }
  if event is Json::Object(_) {
    let kind = field(event, "kind")
    guard kind == None || kind == Some(Json::string("log")) || kind == Some(Json::string("error")) else { return }
    let message = field(event, "msg").or(field(event, "message"))
    guard message is Some(Json::String(text)) else { return }
    let level = field(event, "level")
    self.message(text, debug=level == Some(Json::string("debug")) || level == Some(Json::string("trace")))
  } else {
    // Malformed JSON and binary output are not a safe free-text fallback.
    let text = line.trim().to_owned()
    if text.has_prefix("{") || text.has_prefix("[") { return }
    self.message(text, debug=text.contains(" DEBUG ") || text.contains(" TRACE ") || text.has_prefix("DEBUG ") || text.has_prefix("TRACE "))
  }
}

///|
async fn Progress::read_output(
  self : Progress,
  reader : @process.ReadFromProcess,
  capture~ : Bool,
  statuses? : Bool = false,
  messages? : Bool = false,
) -> String {
  let output = @buffer.Buffer(size_hint=4096)
  let pending = @buffer.Buffer(size_hint=4096)
  let mut oversized = false
  let mut tail = ""
  while reader.read_some(max_len=4096) is Some(chunk) {
    if capture { output.write_bytes(chunk) } else {
      tail += @utf8.decode_lossy(chunk)
      if tail.length() > 8192 { tail = tail[tail.length() - 8192:].to_owned() }
    }
    if !statuses && !messages { continue }
    for byte in chunk {
      if byte == b'\n' || byte == b'\r' {
        if !oversized && pending.length() > 0 {
          let line = @utf8.decode(pending.to_bytes()) catch { _ => "" }
          self.line(line, statuses~, messages~)
        }
        pending.reset()
        oversized = false
      } else if !oversized {
        if pending.length() == 65536 {
          pending.reset()
          oversized = true
        } else { pending.write_byte(byte) }
      }
    }
  }
  if !oversized && pending.length() > 0 {
    let line = @utf8.decode(pending.to_bytes()) catch { _ => "" }
    self.line(line, statuses~, messages~)
  }
  if capture { @utf8.decode(output.to_bytes()) } else { tail }
}
